# resolve local 1..N -> global frame index via manifest order
opus_label = {}
for k, d in OPUS.items():
    manifest = [int(l.split("\t")[0]) for l in open(HERE / "review" / f"batch_{k}.txt")]
    for key, lab in d.items():
        opus_label[manifest[int(key) - 1]] = lab
print("opus-reviewed:", len(opus_label))

records, n_opus = [], 0
for r in ROWS:
    i = r["i"]; img = HERE / "dl" / f"{i}.jpg"
    if not img.exists() or img.stat().st_size == 0: continue
    if i in opus_label:
        lab, src, n_opus = opus_label[i], "opus_review", n_opus + 1
    else:
        lab, src = r["shot"], "v3_scaleup"
    if lab not in CLASSES: continue
    records.append({"image": str(img), "label": lab, "annotator": "ai", "source": src,
                    "confidence": r["conf"], "movie": r["movie"]})
print(f"new scaleup records: {len(records)} (opus {n_opus})")

new = datasets.Dataset.from_list(records)
new = new.cast_column("image", datasets.Image()).cast_column("label", datasets.ClassLabel(names=CLASSES))

cur = load_dataset("szymonrucinski/types-of-film-shots", split="train")
cols = ["image", "label", "annotator", "source", "confidence", "movie"]
human = cur.filter(lambda r: r["annotator"] == "human").select_columns(cols)
ai_old = cur.filter(lambda r: r["annotator"] == "ai").select_columns(cols)
train = concatenate_datasets([ai_old, new.select_columns(cols)])
from collections import Counter
print(f"TRAIN {len(train)}  TEST(human) {len(human)}")
DatasetDict({"train": train, "test": human}).push_to_hub("szymonrucinski/types-of-film-shots", private=False)
print("pushed train/test ->", len(train) + len(human), "rows")
